import{a as s}from"./chunk-WJYJEO3L.js";var t=class i{gifts=[{day:1,title:"Primera sorpresa",image:"/assets/gifts/img1.jpg",riddle:"Tinc agulles i no s\xE9 cosir, s\xF3c verd tot l\u2019any i per Nadal em solen guarnir."},{day:2,title:"Segona sorpresa",image:"/assets/gifts/img2.jpg",riddle:"Em pengen ben amunt, s\xF3c rodona i brillant, i quan arriba Nadal dono llum a cada instant."},{day:3,title:"Tercera sorpresa",image:"/assets/gifts/img3.jpg",riddle:"No tinc ales i puc volar, no tinc boca i puc xiular. Quan arriba l\u2019hivern, em pots notar."},{day:4,title:"Quarta sorpresa",image:"/assets/gifts/img4.jpg",riddle:"S\xF3c blanca i freda, caic del cel sense fer soroll. Si m\u2019ajunto amb moltes com jo, vesteixo de blanc tot el m\xF3n."},{day:5,title:"Cinquena sorpresa",image:"/assets/gifts/img5.jpg",riddle:"Tinc moltes p\xE0gines, per\xF2 no s\xF3c un llibre. Si em mires cada mat\xED, t\u2019explico quin dia \xE9s."},{day:6,title:"Sisena sorpresa",image:"/assets/gifts/img6.JPG",riddle:"S\xF3c petit i dol\xE7, em pengen de l\u2019arbre i sovint tinc forma de bast\xF3."},{day:7,title:"Setena sorpresa",image:"/assets/gifts/img7.jpg",riddle:"Tinc una cara i dues mans, per\xF2 mai no aplaudeixo. T\u2019ajudo a saber quan arriba cada moment."},{day:8,title:"Vuitena sorpresa",image:"/assets/gifts/img8.JPG",riddle:"Com m\xE9s em treus, m\xE9s gran em faig. Qu\xE8 s\xF3c?"},{day:9,title:"Novena sorpresa",image:"/assets/gifts/img9.JPG",riddle:"Em posen al cap quan fa fred, tinc una borla i no s\xF3c cap animal."},{day:10,title:"Desena sorpresa",image:"/assets/gifts/img10.jpg",riddle:"S\xF3c plena de paraules, per\xF2 no parlo. Em pots obrir i descobrir mil hist\xF2ries."},{day:11,title:"Onzena sorpresa",image:"/assets/gifts/img11.JPG",riddle:"No s\xF3c el sol, per\xF2 dono escalfor; no s\xF3c una estrella, per\xF2 brillo a la foscor."},{day:12,title:"Dotzena sorpresa",image:"/assets/gifts/img12.jpg",riddle:"Tinc dents i no menjo, tinc cap i no penso. Sempre em tens al cap."},{day:13,title:"Tretzena sorpresa",image:"/assets/gifts/img13.jpg",riddle:"Com m\xE9s sec estic, m\xE9s m\u2019embruto quan t\u2019eixugo."},{day:14,title:"Catorzena sorpresa",image:"/assets/gifts/img14.jpg",riddle:"Em trenques abans d\u2019utilitzar-me i, quan em cuines, puc ser un bon esmorzar."},{day:15,title:"Quinzena sorpresa",image:"/assets/gifts/img15.jpg",riddle:"S\xF3c rodona com una pilota, per\xF2 no s\xF3c per jugar. Tinc formatge, tom\xE0quet i et puc fer salivar."},{day:16,title:"Setzena sorpresa",image:"/assets/gifts/img16.jpg",riddle:"No estic al cel, tinc cinc puntes i puc decorar l\u2019arbre."},{day:17,title:"Dissetena sorpresa",image:"/assets/gifts/img17.jpg",riddle:"Tinc moltes tecles, per\xF2 no obro cap porta. Si em prems, puc fer m\xFAsica."},{day:18,title:"Divuitena sorpresa",image:"/assets/gifts/img18.jpg",riddle:"Em poses als peus per sortir al carrer, per\xF2 mai no camino sola."},{day:19,title:"Dinovena sorpresa",image:"/assets/gifts/img19.jpg",riddle:"S\xF3c dol\xE7, calent i sovint em beus quan fa fred."},{day:20,title:"Vintena sorpresa",image:"/assets/gifts/img20.jpg",riddle:"No tinc cames, per\xF2 pujo i baixo. Tinc graons i t\u2019ajudo a arribar m\xE9s amunt."},{day:21,title:"Vint-i-unena sorpresa",image:"/assets/gifts/img21.JPG",riddle:"S\xF3c un regal que no pots embolicar, per\xF2 quan em comparteixes pots fer feli\xE7 alg\xFA."},{day:22,title:"Vint-i-dosena sorpresa",image:"/assets/gifts/img22.jpg",riddle:"Tinc un coll, per\xF2 no tinc cap; tinc m\xE0nigues, per\xF2 no tinc bra\xE7os. A l\u2019hivern em poses per no passar fred."},{day:23,title:"Vint-i-tresena sorpresa",image:"/assets/gifts/img23.JPG",riddle:"Arribo despr\xE9s del dia i abans del mat\xED. Quan aparec, el cel s\u2019omple d\u2019estrelles."},{day:24,title:"Vint-i-quatrena sorpresa",image:"/assets/gifts/img24.jpg",riddle:"S\xF3c un dia molt especial, arribo el 25 de desembre i celebro una festa plena de m\xE0gia."}];getGifts(){return this.gifts}getGift(a){return this.gifts.find(e=>e.day===a)}isGiftAvailable(a){let e=new Date;return e.getMonth()===11&&e.getDate()>=a}static \u0275fac=function(e){return new(e||i)};static \u0275prov=s({token:i,factory:i.\u0275fac,providedIn:"root"})};export{t as a};
